// Decrypts the content in payload.js (generated by encrypt.py) with the entered password.
// The page content is never present in plaintext in the published site.

const SESSION_KEY = "site-key";

const gate = document.getElementById("gate");
const form = document.getElementById("gate-form");
const input = document.getElementById("password");
const error = document.getElementById("error");
const content = document.getElementById("content");
const button = form.querySelector("button");

function fromBase64(str) {
  return Uint8Array.from(atob(str), (c) => c.charCodeAt(0));
}

function toBase64(bytes) {
  return btoa(String.fromCharCode(...new Uint8Array(bytes)));
}

async function deriveKeyBytes(password) {
  const baseKey = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]
  );
  return crypto.subtle.deriveBits(
    { name: "PBKDF2", salt: fromBase64(PAYLOAD.salt), iterations: PAYLOAD.iterations, hash: "SHA-256" },
    baseKey,
    256
  );
}

async function decrypt(keyBytes) {
  const key = await crypto.subtle.importKey("raw", keyBytes, "AES-GCM", false, ["decrypt"]);
  const plaintext = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: fromBase64(PAYLOAD.iv) },
    key,
    fromBase64(PAYLOAD.ciphertext)
  );
  return new TextDecoder().decode(plaintext);
}

function show(html) {
  content.innerHTML = html;
  gate.hidden = true;
  content.hidden = false;
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  error.hidden = true;
  button.disabled = true;
  try {
    const keyBytes = await deriveKeyBytes(input.value);
    show(await decrypt(keyBytes));
    try {
      sessionStorage.setItem(SESSION_KEY, toBase64(keyBytes));
    } catch {}
  } catch {
    error.hidden = false;
    input.select();
  } finally {
    button.disabled = false;
  }
});

// Stay unlocked across reloads within the same browser tab.
(async () => {
  let saved = null;
  try {
    saved = sessionStorage.getItem(SESSION_KEY);
  } catch {}
  if (!saved) return;
  try {
    show(await decrypt(fromBase64(saved)));
  } catch {
    try {
      sessionStorage.removeItem(SESSION_KEY);
    } catch {}
  }
})();
